	Point3<T> operator + (const Point3<T>& otherPoint)    const;
	Point3<T> operator - (const T& scalar)               const;
	Point3<T> operator - (const Point3<T>& otherPoint)    const;
	Point3<T> operator * (const T& scalar)               const;
	Point3<T> operator * (const Point3<T>& otherPoint)    const;
	Point3<T> operator / (const T& scalar )              const;
