template<class T>
inline double Point3<T>::angleRAD(const Point3<T>& otherVector) const
{
	Point3<T> u = *this; u.normalize();
	Point3<T> v = otherVector;    v.normalize();
    double dot   = std::min( 1.0, u.dot(v));
